static bool wait_for_event(atomic_t *events, int bit, k_timeout_t timeout)
{
	int64_t start_time = k_uptime_get();
	int64_t timeout_ticks = timeout.ticks;

	while (!atomic_test_bit(events, bit)) {
		if (k_uptime_get() - start_time > timeout_ticks) {
			return false;
		}
		k_sleep(K_MSEC(10)); /* Poll every 10ms */
	}
	return true;
}

